/**
 * Express middleware that authenticates MCP requests.
 * Extracts the API key, validates it, and attaches it to the request.
 */
export async function authenticateMCP(
  req: Request,
  res: Response,
  next: NextFunction,
): Promise<void> {
  const apiKey = extractApiKey(req);

  // Allow unauthenticated access in development when no server key is configured
  const hasServerKey =
    !!process.env.BUILT_IN_FORGE_API_KEY?.trim() ||
    !!process.env.GRAVITO_API_KEY?.trim() ||
    !!process.env.GravitoAPI?.trim();
  if (process.env.NODE_ENV === 'development' && !hasServerKey) {
    (req as Request & { apiKey?: string }).apiKey = 'dev-mode';
    return next();
  }

  if (!apiKey) {
    res.status(401).json({
      jsonrpc: '2.0',
      error: {
        code: -32000,
        message: 'Authentication required. Provide API key via Authorization: Bearer <key> header.',
      },
    });
    return;
  }

  const isValid = await validateApiKey(apiKey);
  if (!isValid) {
    res.status(403).json({
      jsonrpc: '2.0',
      error: {
        code: -32000,
        message: 'Invalid API key.',
      },
    });
    return;
  }

  // Attach key to request for downstream use
  (req as Request & { apiKey?: string }).apiKey = apiKey;
  next();
}

