/**
 * MCP HTTP Handler
 * 
 * Exposes the Gravito MCP server via HTTP endpoints for Manus Custom MCP integration.
 * Implements the MCP protocol over HTTP with API key authentication (NOT OAuth).
 * 
 * Authentication:
 * - Authorization: Bearer <api_key>
 * - x-gravito-api-key: <api_key>
 * 
 * Endpoints:
 * - GET /api/mcp/health - Health check with auth metadata
 * - POST /api/mcp/tools/list - List available tools with auth metadata
 * - POST /api/mcp/tools/call - Call a specific tool
 */

import { Router, Request, Response, NextFunction } from 'express';
import { isAllowedGovernanceCorsOrigin } from '../_core/public-origin-allowlist';
import { z } from 'zod';
import { mcpError, classifyError } from './mcp-error-contract';
import { buildCustomerErrorResponse, type DegradedResponse } from '../governance/degraded-response';
import { runInternalAnalysis } from '../governance/internal-analyzer';
import { isRegulatedSurface } from '../governance/transport-error-mapper';
import { withIdempotentRetry } from '../governance/idempotent-retry';
import { getAllCircuitBreakerMetrics } from '../governance/circuit-breaker';
import { resolveGovernedAuthenticatedTenant } from '../governance/governed-authenticated-tenant';
import { isFeatureEnabled } from '../emotional-geometry-runtime/feature-flags';
import { recordLatencyObservation } from '../observability/prometheus-metrics';
import { recordGovernedCheck } from '../billing/governed-usage-meter';
