  VerifyClaimInputSchema,
  ComposeEmailInputSchema,
  type ReviewContentInput,
  type GovernanceAuditInput,
  type VerifyClaimInput,
  type ComposeEmailInput,
} from '../agent/mcp/gravito-mcp-server';

import {
  getCreativePartnerService,
  CREATIVE_PARTNER_TOOLS,
  GenerateArtifactInputSchema,
  GenerateVariantsInputSchema,
  SelectWinnerInputSchema,
  CreateExperimentInputSchema,
