});


// ============================================================================
// HELPER: Convert Zod schema to JSON Schema
// ============================================================================

function zodToJsonSchema(schema: z.ZodType<any>, definitions?: Map<string, any>): any {
  // Basic conversion - for full compatibility, use zod-to-json-schema package
  const description = (schema as unknown as Record<string, unknown>).description || '';
  const def = (schema as unknown as Record<string, unknown>)._def;

  // Check for enum using multiple detection methods
  // Zod 3.x uses _def.type === 'enum' and _def.entries
  if (def?.type === 'enum' && def?.entries) {
    return {
      type: 'string',
      enum: Object.keys(def.entries),
      description,
    };
  }

  // Zod 3.x alternative: check typeName
  if (def?.typeName === 'ZodEnum') {
    return {
      type: 'string',
      enum: def.values || Object.keys(def.entries || {}),
      description,
    };
  }

  if (def?.typeName === 'ZodNativeEnum') {
    return {
      type: 'string',
      enum: Object.values(def.values),
      description,
    };
  }

  if (schema instanceof z.ZodObject) {
    const shape = schema.shape;
    const properties: Record<string, unknown> = {};
    const required: string[] = [];

    for (const [key, value] of Object.entries(shape)) {
      properties[key] = zodToJsonSchema(value as z.ZodType<any>, definitions);
      if (!(value as unknown as Record<string, unknown>).isOptional?.()) {
        required.push(key);
      }
    }

    return {
      type: 'object',
      properties,
      required: required.length > 0 ? required : undefined,
      description,
    };
  }

  if (schema instanceof z.ZodString) {
    return { type: 'string', description };
  }

  if (schema instanceof z.ZodNumber) {
    return { type: 'number', description };
  }

  if (schema instanceof z.ZodBoolean) {
    return { type: 'boolean', description };
  }

  if (schema instanceof z.ZodArray) {
    return {
      type: 'array',
      items: zodToJsonSchema((schema as unknown as Record<string, unknown>)._def.type, definitions),
      description,
    };
  }

  // ZodEnum already handled above via typeName check
  if (schema instanceof z.ZodEnum) {
    return {
      type: 'string',
      enum: (schema as unknown as Record<string, unknown>)._def.values,
      description,
    };
  }

  if (schema instanceof z.ZodDefault) {
    const inner = zodToJsonSchema((schema as unknown as Record<string, unknown>)._def.innerType, definitions);
    try {
      const defaultVal = (schema as unknown as Record<string, unknown>)._def.defaultValue;
      inner.default = typeof defaultVal === 'function' ? defaultVal() : defaultVal;
    } catch {
      // Ignore default value extraction errors
    }
    return inner;
  }

  if (schema instanceof z.ZodOptional) {
    return zodToJsonSchema((schema as unknown as Record<string, unknown>)._def.innerType, definitions);
  }

  // Fallback
  return { type: 'any', description };
}

// ============================================================================
// USAGE STATS ENDPOINT (Authenticated - for dashboard/billing)
// ============================================================================

mcpRouter.get('/usage', authenticateMCP, async (req: Request, res: Response) => {
  try {
    const period = (req.query.period as string) || '24h';
    const since = new Date();
    switch (period) {
      case '1h': since.setHours(since.getHours() - 1); break;
      case '24h': since.setHours(since.getHours() - 24); break;
      case '7d': since.setDate(since.getDate() - 7); break;
      case '30d': since.setDate(since.getDate() - 30); break;
      default: since.setHours(since.getHours() - 24);
    }

    const stats = await getUsageStats(since);
    res.json({
      period,
      since: since.toISOString(),
      ...stats,
    });
  } catch (error) {
    generalLog.error('[MCP Usage] Error:', error);
    res.status(500).json({ error: 'Failed to retrieve usage stats' });
  }
});

