              nexus: ['getNexusOverview', 'getSurfaceMap', 'getRiskHeatmap', 'getOutcomeLift'],
              operations: ['breakGlass', 'breakGlassDrill', 'runAutoExpire', 'runEscalation',
                'listBreakGlass', 'approveBreakGlass', 'revokeBreakGlass',
                'certifyRelease', 'exportReport', 'appealDecision', 'scheduleAudit'],
              financial: ['reviewTradingThesis', 'reviewTradeProposal', 'reviewStrategyChange', 'trackTradingOutcome'],
              safety: ['validateToolCall', 'detectPromptInjection', 'enforceEscalation', 'routeModel',
                'classifyClaims', 'requireEvidence', 'validateTruthSurface'],
              narrative_coherence: ['auditNarrativeCoherence', 'quickNarrativeCheck', 'discoverContentUnits', 'auditDocsCoherence'],
              content_digestibility: ['auditDigestibility', 'getDigestibilityHistory'],
            };

            // Determine tool health status
            type ToolHealthStatus = 'functional' | 'schema_override' | 'content_passthrough' | 'stub';
            const getToolHealth = (toolName: string): { status: ToolHealthStatus; schema: any | null } => {
              const shortName = toolName.replace('gravito.', '');
              const hasSchemaOverride = !!BRIDGE_TOOL_SCHEMAS[shortName];
              const hasCaseHandler = ALL_TOOLS.some(t => t.name === `gravito.${shortName}` && !t.name.includes('bridge'));

              // Tools with explicit case handlers are functional
              const explicitHandlers = [
                'reviewContent', 'governanceAudit', 'verifyClaim', 'composeEmail',
                'reviewTradingThesis', 'reviewTradeProposal', 'reviewStrategyChange', 'trackTradingOutcome',
                'checkCompliance', 'getDecisionTrace', 'generateArtifact', 'generateVariants',
                'experimentDesign', 'compareVariants', 'structureCreativity',
                'getNexusOverview', 'getSurfaceMap', 'recordOutcome', 'getRiskHeatmap', 'getOutcomeLift',
                'getCapabilities', 'checkApprovedClaims', 'enforceDisclaimers', 'detectForbiddenLanguage',
                'validateCitations', 'exportAuditTrail', 'reviewSequence', 'checkPersonalization',
                'enforceBrandVoice', 'trackReplyRate', 'validateToolCall', 'detectPromptInjection',
                'enforceEscalation', 'routeModel', 'classifyClaims', 'requireEvidence', 'validateTruthSurface',
                'clarifyIntent', 'simulatePerception', 'detectAbstraction', 'checkCoherence',
                'suggestRefinement', 'runCreativeIntegrity', 'selectWinnerCandidate', 'createExperiment',
                'publishPatch', 'autopilotCycle', 'certifyRelease', 'exportReport', 'appealDecision',
                'scheduleAudit', 'approveBreakGlass', 'revokeBreakGlass',
                'checkContentEnforcement', 'governedGenerate',
                'auditNarrativeCoherence', 'quickNarrativeCheck', 'discoverContentUnits', 'auditDocsCoherence',
                'auditDigestibility', 'getDigestibilityHistory',
              ];

              const schema = hasSchemaOverride ? BRIDGE_TOOL_SCHEMAS[shortName].inputSchema : null;

              if (explicitHandlers.includes(shortName)) {
                return { status: 'functional', schema };
              }
              if (hasSchemaOverride) {
                return { status: 'schema_override', schema };
              }
              // Bridge tools that accept content:string passthrough
              return { status: 'content_passthrough', schema: { type: 'object', properties: { content: { type: 'string' } }, required: ['content'] } };
            };

            // Build the report
            const filterCategory = category && category !== 'all' ? category : null;
            const report: any = {
              version: '1.0.0',
              timestamp: new Date().toISOString(),
              total_tools: ALL_TOOLS.length,
              summary: {
                functional: 0,
                schema_override: 0,
                content_passthrough: 0,
              },
              categories: {} as unknown as Record<string, unknown>,
            };

            for (const [cat, toolNames] of Object.entries(toolCategories)) {
              if (filterCategory && cat !== filterCategory) continue;
              const tools = toolNames.map(name => {
                const health = getToolHealth(name);
                report.summary[health.status] = (report.summary[health.status] || 0) + 1;
                return {
                  name: `gravito.${name}`,
                  status: health.status,
                  ...(includeSchemas && health.schema ? { inputSchema: health.schema } : {}),
                  description: BRIDGE_TOOL_SCHEMAS[name]?.description || ALL_TOOLS.find(t => t.name === `gravito.${name}`)?.description || '',
                };
              });
              report.categories[cat] = { count: tools.length, tools };
            }

            // Add uncategorized bridge tools
            if (!filterCategory) {
              const allCategorized = Object.values(toolCategories).flat();
              const uncategorized = ALL_TOOLS
                .filter(t => !allCategorized.includes(t.name.replace('gravito.', '')))
                .map(t => ({
                  name: t.name,
                  status: getToolHealth(t.name).status,
                  description: t.description || '',
