        contentUnits: { type: 'array' as const, items: { type: 'object' as const }, description: 'Pre-extracted content units for generic surface' },
      },
      required: [] as string[],
    },
  },
  {
    name: 'gravito.getDigestibilityHistory',
    description: 'Get the history of content digestibility audits, including scores and trends.',
    inputSchema: {
      type: 'object' as const,
      properties: {},
      required: [] as string[],
    },
  },
];

// Add digestibility tools to ALL_TOOLS_DEDUPED
for (const tool of DIGESTIBILITY_TOOLS) {
