// ============================================================================
// HELPER: Convert Zod schema to JSON Schema
// ============================================================================

/**
 * The subset of JSON Schema this converter emits. Tool catalogs mix
 * hand-written JSON Schema literals with Zod schemas, so the converted output
 * needs a name of its own to stay comparable with the literals.
 */
interface JsonSchemaNode {
  type: string;
  description: string;
  enum?: string[];
  properties?: Record<string, JsonSchemaNode>;
  required?: string[];
  items?: JsonSchemaNode;
  default?: unknown;
}

/**
 * Narrow a catalog entry's `inputSchema` to a Zod schema. Tools registered
 * through the bridge carry plain JSON Schema objects; tools registered from
 * Zod carry real schema instances. Only the latter need conversion.
 */
function isZodSchema(schema: unknown): schema is z.ZodType {
  return schema instanceof z.ZodType;
}

/**
 * Zod types child schemas inside `_def` as core `$ZodType`. Every schema this
 * converter walks is built from the classic `z` namespace, so the classic view
 * is recovered here once rather than at each recursion site.
 */
function classicSchema(schema: z.core.$ZodType): z.ZodType {
  return schema as z.ZodType;
}

function zodToJsonSchema(schema: z.ZodType, definitions?: Map<string, JsonSchemaNode>): JsonSchemaNode {
  // Basic conversion - for full compatibility, use zod-to-json-schema package
  const description = schema.description || '';

  // Enums (including native enums, which Zod 4 also represents as ZodEnum).
  // `_def.entries` is the name→value record backing the enum.
  if (schema instanceof z.ZodEnum) {
    return {
      type: 'string',
      enum: Object.keys(schema._def.entries),
      description,
    };
  }

  if (schema instanceof z.ZodObject) {
    const properties: Record<string, JsonSchemaNode> = {};
    const required: string[] = [];

    for (const [key, value] of Object.entries(schema.shape)) {
      properties[key] = zodToJsonSchema(value, definitions);
      if (!value.isOptional()) {
        required.push(key);
      }
    }

    return {
      type: 'object',
      properties,
      required: required.length > 0 ? required : undefined,
      description,
    };
  }

  if (schema instanceof z.ZodString) {
    return { type: 'string', description };
  }

  if (schema instanceof z.ZodNumber) {
    return { type: 'number', description };
  }

  if (schema instanceof z.ZodBoolean) {
    return { type: 'boolean', description };
  }

  if (schema instanceof z.ZodArray) {
    return {
      type: 'array',
      items: zodToJsonSchema(classicSchema(schema._def.element), definitions),
      description,
    };
  }

  if (schema instanceof z.ZodDefault) {
    const inner = zodToJsonSchema(schema._def.innerType, definitions);
    try {
      const defaultVal: unknown = schema._def.defaultValue;
      inner.default = typeof defaultVal === 'function' ? defaultVal() : defaultVal;
    } catch {
      // Ignore default value extraction errors
    }
    return inner;
  }

  if (schema instanceof z.ZodOptional) {
    return zodToJsonSchema(schema._def.innerType, definitions);
  }

  // Fallback
  return { type: 'any', description };
}

// ============================================================================
